pub fn parseFontStyle(input: *css.Parser) css.Result(FontStyle) {
        const location = input.currentSourceLocation();
        const ident_res = input.expectIdent();
        if ((ident_res == .err)) {
            return .{ .err = ident_res.err };
        }
        const ident = ident_res.result;
        if (bun.strings.eqlCaseInsensitiveASCIIICheckLength("normal", ident)) {
            return .{ .result = .normal };
        } else {
            if (bun.strings.eqlCaseInsensitiveASCIIICheckLength("italic", ident)) {
                return .{ .result = .italic };
            } else {
                if (bun.strings.eqlCaseInsensitiveASCIIICheckLength("oblique", ident)) {
                    const angle = input.tryParse(Angle.parse, .{}).unwrapOr(FontStyle.defaultObliqueAngle());
                    return .{ .result = .{ .oblique = angle } };
                } else {
                    return .{ .err = location.newUnexpectedTokenError(.{ .ident = ident }) };
                }
            }
        }
}

pub fn toCssFontStyle(this_fs: *const FontStyle, dest: *Printer) PrintErr!void {
        switch (this_fs.*) {
.normal => {
_ = try dest.writeStr("normal");
},
.italic => {
_ = try dest.writeStr("italic");
},
.oblique => |angle| {
_ = try dest.writeStr("oblique");
        if ((!angle.eql((&FontStyle.defaultObliqueAngle())))) {
            _ = try dest.writeChar(32);
            _ = try angle.toCss(dest);
        }
},
}
}

pub inline fn compatibleFontFamily(allocator: std.mem.Allocator, _family: ?bun.BabyList(FontFamily), is_supported: bool) ?bun.BabyList(FontFamily) {
        var family = _family;
        _ = &family;
        if (is_supported) {
            return family;
        }
        if (family) |*families| {
            _ = &families;
            const slice_c = (families.*).sliceConst();
            var i: usize = 0;
            _ = &i;
            while ((i < slice_c.len)) : (i = (i + 1)) {
                const v = slice_c[@as(usize, @intCast(i))];
                const system_ui = SYSTEM_UI;
                if (v.eql((&system_ui))) {
                    var j: usize = 0;
                    _ = &j;
                    while ((j < DEFAULT_SYSTEM_FONTS.len)) : (j = (j + 1)) {
                        const name = DEFAULT_SYSTEM_FONTS[@as(usize, @intCast(j))];
                        _ = bun.handleOom((families.*).insert(allocator, ((i + j) + 1), .{ .family_name = name }));
                    }
                    break;
                }
            }
        }
        return family;
}

pub inline fn isFontProperty(property_id: css.PropertyId) bool {
        return (switch (property_id) {
.@"font-family", .@"font-size", .@"font-style", .@"font-weight", .@"font-stretch", .@"font-variant-caps", .@"line-height", .font => true,
else => false,
});
